            op.Process();
        } else {
            KernelMuls<half> op;
            op.Init(x, y, scalarVal, formerNum, formerLength, tailLength, tileLength);
            op.Process();
        }
    } else {
        KernelMuls<float> op;
        op.Init(x, y, scalarVal, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
