19	at::Tensor muls_npu(const at::Tensor &self, const at::Tensor &value)
20	{
21	    // ---- input validation ----
22	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat ||
23	                self.scalar_type() == at::kBFloat16,
24	                "muls_npu: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
25	
26	    at::Tensor output = at::empty_like(self);
27	
28	    int64_t totalLength = self.numel();
29	    if (totalLength == 0) {
30	        return output;
31	    }
32	
33	    int64_t dtypeSize = self.element_size();
34	
35	    // ---- extract scalar from value tensor ----
36	    float scalarVal = value.cpu().item<float>();
37	
38	    // ---- get hardware params ----
39	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
40	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
41	    uint64_t ubSize;
42	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
43	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
44	
45	    // ---- Block level tiling (inter-core split, Cache Line aligned) ----
46	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
47	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
48	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
49	
50	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
51	    int64_t formerNum = usedCoreNum - 1;
52	    int64_t formerLength = totalLengthCoreAlign;
53	    int64_t tailLength = totalLength - formerNum * formerLength;
54	
55	    // ---- UB level tiling (intra-core split) ----
56	    // bufferCoefficient from UB allocation table:
57	    //   float32 single input: 20
58	    //   float16/bfloat16 single input: 16 (needs extra float32 buffer for cast)
59	    int64_t bufferCoefficient = (dtypeSize == 4) ? 20 : 16;
60	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
61	    int64_t alignElements = 32 / dtypeSize;
62	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
63	
64	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
65	
66	    // All parameters must be left values (named variables)
67	    int64_t tailLengthLval = tailLength;
68	    int64_t tileLengthLval = tileLength;
69	    int64_t dtypeSizeLval = dtypeSize;
70	    EXEC_KERNEL_CMD(muls, blockDim,
71	                    self, output, scalarVal,
72	                    formerNum, formerLength, tailLengthLval, tileLengthLval, dtypeSizeLval);
73	
74	    return output;
75	}
