from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "muls_ext*")

# Priority: whl import (triggers TORCH_LIBRARY registration)
try:
    import muls_ext  # noqa: F401
except ImportError:
    # Fallback: direct .so loading
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


def get_init_inputs():
    return []


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor, value: torch.Tensor):
        # Convert value scalar to float32 (matching kernel capability)
        val_f32 = value.to(torch.float32)

        # Handle integer types: convert to float32
        if x.dtype in (torch.int32, torch.int16):
            out_f32 = torch.ops.npu.muls_npu(x.to(torch.float32), val_f32)
            return out_f32.to(torch.float64)

        # Handle complex64: real/imag separately, each through kernel
        if x.is_complex():
            out_real = torch.ops.npu.muls_npu(x.real, val_f32)
            out_imag = torch.ops.npu.muls_npu(x.imag, val_f32)
            result = torch.empty(x.shape, dtype=torch.complex128, device=x.device)
            result.real.copy_(out_real.to(torch.float64))
            result.imag.copy_(out_imag.to(torch.float64))
            return result

        # For float16/bf16/float32: convert value to x.dtype for precision matching,
        # kernel computes in x.dtype, then cast output to float64 to match golden dtype
        val_matched = val_f32.to(x.dtype)
        out = torch.ops.npu.muls_npu(x, val_matched)
        return out.to(torch.float64)
